-- 02-seed.sql — FILE TỰ SINH bởi database/seed/generate.js, đừng sửa tay.
-- Dữ liệu mẫu LUXE: 8 danh mục, 45 sản phẩm, đánh giá và 2 tài khoản demo.
-- Chạy lại nhiều lần an toàn (UPSERT theo id), dùng: bash scripts/seed-db.sh
--   Admin: admin@luxe.vn / Admin@123
--   Khách: demo@luxe.vn  / Demo@123

SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE full_name = VALUES(full_name), role = VALUES(role);

ON DUPLICATE KEY UPDATE name = VALUES(name), slug = VALUES(slug), description = VALUES(description),
  image_url = VALUES(image_url), sort_order = VALUES(sort_order);

  stock, sold, sizes, color, material, gender, rating, review_count, is_featured, is_new, image_url, images) VALUES
  (1, 1, 'Đầm dạ hội trễ vai họa tiết hoa', 'dam-da-hoi-tre-vai-hoa', 'LUXE', 'Đầm dạ hội dáng dài chấm gót với phần cúp ngực và dải vai đen trễ vai thanh lịch. Nền đen sâu in hoạ tiết hoa hồng, tím mộng mơ và lá xanh ngọc rực rỡ, chân váy suông rủ mềm tạo dáng cao ráo khi di chuyển.', '["Cổ trễ vai với dải viền đen ôm khít","Hoạ tiết hoa nhiều màu trên nền đen","Dáng dài chấm gót, chân váy rủ mềm","Khoá kéo ẩn sau lưng"]', 1890000, 2290000, 18, 64, 'XS,S,M,L', 'Đen hoa', 'Lụa satin in kỹ thuật số', 'nu', 5, 3, 1, 0, '/images/products/dam-da-hoi-tre-vai-hoa-1.webp', '["/images/products/dam-da-hoi-tre-vai-hoa-1.webp","/images/products/dam-da-hoi-tre-vai-hoa-2.webp","/images/products/dam-da-hoi-tre-vai-hoa-3.webp","/images/products/dam-da-hoi-tre-vai-hoa-4.webp"]'),
  (2, 1, 'Đầm corset da đỏ chân váy dài', 'dam-corset-da-do', 'LUXE', 'Đầm cúp ngực với phần thân trên kiểu corset bằng da đỏ tươi ôm sát, chia mảnh định hình eo. Chân váy dài cùng tông đỏ rủ thành những nếp gấp tự nhiên, nổi bật cho tiệc tối và sự kiện.', '["Thân trên corset chia mảnh tôn eo","Cúp ngực không dây","Chân váy dài xếp nếp tự nhiên","Tông đỏ đồng bộ toàn thân"]', 2150000, NULL, 12, 31, 'XS,S,M,L', 'Đỏ', 'Da PU bóng mờ', 'nu', 4.6, 5, 1, 1, '/images/products/dam-corset-da-do-1.webp', '["/images/products/dam-corset-da-do-1.webp","/images/products/dam-corset-da-do-2.webp","/images/products/dam-corset-da-do-3.webp","/images/products/dam-corset-da-do-4.webp"]'),
  (3, 1, 'Đầm corset da đen dáng dài', 'dam-corset-da-den', 'LUXE', 'Phiên bản đen huyền bí của dòng đầm corset: thân trên cúp ngực bằng da đen ôm dáng, chân váy dài chấm đất rủ nếp mềm. Tối giản, quyền lực và dễ phối cùng trang sức kim loại.', '["Corset cúp ngực ôm dáng","Chân váy dài chấm đất","Màu đen dễ phối phụ kiện","Khoá kéo ẩn phía sau"]', 2150000, NULL, 15, 42, 'XS,S,M,L', 'Đen', 'Da PU bóng mờ', 'nu', 4.4, 5, 0, 0, '/images/products/dam-corset-da-den-1.webp', '["/images/products/dam-corset-da-den-1.webp","/images/products/dam-corset-da-den-2.webp","/images/products/dam-corset-da-den-3.webp","/images/products/dam-corset-da-den-4.webp"]'),
  (4, 1, 'Đầm xoè chấm bi đính nơ retro', 'dam-xoe-cham-bi-no', 'LUXE', 'Đầm cúp ngực nền trắng in chấm bi đỏ nhỏ, viền mép đỏ tinh tế. Nơ bản to cùng chất liệu đính bên eo, chân váy xoè bồng nhiều lớp mang đúng tinh thần retro thập niên 50.', '["Nơ lớn đính eo","Chân váy xoè bồng có lót","Viền đỏ ở cổ và gấu váy","Phong cách vintage thập niên 50"]', 990000, 1190000, 26, 88, 'XS,S,M,L', 'Trắng chấm bi đỏ', 'Cotton pha, lót tafta', 'nu', 4.8, 6, 0, 0, '/images/products/dam-xoe-cham-bi-no-1.webp', '["/images/products/dam-xoe-cham-bi-no-1.webp","/images/products/dam-xoe-cham-bi-no-2.webp","/images/products/dam-xoe-cham-bi-no-3.webp","/images/products/dam-xoe-cham-bi-no-4.webp"]'),
  (5, 1, 'Đầm suông dài phối màu color-block', 'dam-suong-phoi-mau-color-block', 'LUXE', 'Đầm suông dáng dài cổ tròn viền cam đào, phối khối màu táo bạo: mặt trước đỏ đô (burgundy), mặt sau đen, một tay hồng fuchsia và một tay trắng kem. Thiết kế mang hơi hướng runway, hợp phong cách cá tính.', '["Phối 4 khối màu bất đối xứng","Tay dài hai màu khác nhau","Cổ tròn viền cam đào","Dáng suông dài qua gối"]', 1250000, NULL, 20, 17, 'S,M,L,XL', 'Đỏ đô / Đen / Hồng / Trắng', 'Crepe co giãn nhẹ', 'nu', 5, 3, 0, 1, '/images/products/dam-suong-phoi-mau-color-block-1.webp', '["/images/products/dam-suong-phoi-mau-color-block-1.webp","/images/products/dam-suong-phoi-mau-color-block-2.webp","/images/products/dam-suong-phoi-mau-color-block-3.webp","/images/products/dam-suong-phoi-mau-color-block-4.webp"]'),
  (6, 1, 'Đầm xoè tay cánh tiên chấm tròn xanh', 'dam-xoe-tay-canh-tien-cham-tron', 'LUXE', 'Đầm xoè ngang gối nền xanh baby in chấm tròn nhiều kích cỡ màu xanh dương và tím lavender. Tay cánh tiên ngắn bồng nhẹ, eo chiết và chân váy xoè rộng cho vẻ ngoài trẻ trung, nữ tính.', '["Tay cánh tiên bồng nhẹ","Hoạ tiết chấm tròn xanh – tím","Chân váy xoè ngang gối","Cổ tròn dễ mặc"]', 690000, NULL, 35, 120, 'XS,S,M,L', 'Xanh baby', 'Cotton lụa', 'nu', 4.7, 3, 0, 0, '/images/products/dam-xoe-tay-canh-tien-cham-tron-1.webp', '["/images/products/dam-xoe-tay-canh-tien-cham-tron-1.webp","/images/products/dam-xoe-tay-canh-tien-cham-tron-2.webp","/images/products/dam-xoe-tay-canh-tien-cham-tron-3.webp","/images/products/dam-xoe-tay-canh-tien-cham-tron-4.webp"]'),
  (7, 1, 'Đầm maxi hai dây trễ vai lá cọ', 'dam-maxi-hai-day-la-co', 'LUXE', 'Đầm maxi dáng dài suông với dây mảnh và lớp bèo trễ vai nhún nhẹ. Nền trắng in hoạ tiết lá cọ đen đồ hoạ, rất hợp đi biển, du lịch hay dạo phố ngày hè.', '["Hai dây mảnh kết hợp bèo trễ vai","Hoạ tiết lá cọ đen trắng","Dáng maxi suông thoải mái","Chất voan nhẹ, thoáng mát"]', 790000, NULL, 28, 95, 'XS,S,M,L', 'Trắng / Đen', 'Voan lụa', 'nu', 4.3, 3, 1, 0, '/images/products/dam-maxi-hai-day-la-co-1.webp', '["/images/products/dam-maxi-hai-day-la-co-1.webp","/images/products/dam-maxi-hai-day-la-co-2.webp","/images/products/dam-maxi-hai-day-la-co-3.webp","/images/products/dam-maxi-hai-day-la-co-4.webp"]'),
  (8, 1, 'Đầm midi sát nách màu be đính cúc', 'dam-midi-sat-nach-be-dinh-cuc', 'LUXE', 'Đầm midi sát nách tông be xám trung tính, cổ tròn với hàng cúc nhỏ chạy dọc thân trước. Đai vải rút eo tạo dáng, lưng khoét chữ U nhẹ – lựa chọn thanh lịch cho công sở lẫn cuối tuần.', '["Hàng cúc nhỏ dọc thân trước","Đai vải thắt eo","Lưng khoét chữ U","Chất linen thoáng, đứng form"]', 850000, NULL, 30, 73, 'S,M,L,XL', 'Be xám', 'Linen pha cotton', 'nu', 4.7, 6, 0, 0, '/images/products/dam-midi-sat-nach-be-dinh-cuc-1.webp', '["/images/products/dam-midi-sat-nach-be-dinh-cuc-1.webp","/images/products/dam-midi-sat-nach-be-dinh-cuc-2.webp","/images/products/dam-midi-sat-nach-be-dinh-cuc-3.webp","/images/products/dam-midi-sat-nach-be-dinh-cuc-4.webp"]'),
  (9, 1, 'Đầm cúp ngực xanh mint tầng bèo', 'dam-cup-nguc-xanh-mint-tang', 'LUXE', 'Đầm cúp ngực màu xanh mint pha xám dịu mắt, nơ to thắt ngang eo. Chân váy hai tầng xoè trên gối tạo độ bồng nhẹ nhàng, phù hợp tiệc ngoài trời và dạo phố.', '["Cúp ngực ôm vừa","Nơ vải thắt eo","Chân váy hai tầng xoè","Độ dài trên gối"]', 920000, 1090000, 22, 39, 'XS,S,M,L', 'Xanh mint xám', 'Cotton twill', 'nu', 4.5, 4, 0, 1, '/images/products/dam-cup-nguc-xanh-mint-tang-1.webp', '["/images/products/dam-cup-nguc-xanh-mint-tang-1.webp","/images/products/dam-cup-nguc-xanh-mint-tang-2.webp","/images/products/dam-cup-nguc-xanh-mint-tang-3.webp","/images/products/dam-cup-nguc-xanh-mint-tang-4.webp"]'),
  (10, 1, 'Đầm caro tartan thắt nơ satin đen', 'dam-caro-tartan-no-satin', 'LUXE', 'Đầm sát nách hoạ tiết caro tartan đen – trắng – xám, phần eo nhấn đai satin đen thắt nơ bản lớn phía sau lưng. Chân váy xoè, cổ tròn – phong cách preppy cổ điển.', '["Caro tartan đơn sắc","Đai satin đen thắt nơ lớn","Chân váy xoè ngang gối","Sát nách, cổ tròn"]', 760000, NULL, 32, 58, 'XS,S,M,L', 'Caro đen – trắng – xám', 'Cotton dệt caro, đai satin', 'nu', 4.4, 5, 0, 0, '/images/products/dam-caro-tartan-no-satin-1.webp', '["/images/products/dam-caro-tartan-no-satin-1.webp","/images/products/dam-caro-tartan-no-satin-2.webp","/images/products/dam-caro-tartan-no-satin-3.webp","/images/products/dam-caro-tartan-no-satin-4.webp"]'),
  (11, 2, 'Sơ mi caro gingham xanh dương', 'so-mi-caro-gingham-xanh-duong', 'LUXE', 'Sơ mi nam tay dài kẻ caro gingham phối xanh dương, xanh navy và trắng. Cổ bẻ, nẹp nút giữa, túi ngực trái và măng-sét cài nút – vừa vặn cho đi làm lẫn đi chơi.', '["Caro gingham xanh – trắng","Túi ngực trái","Măng-sét cài nút","Form regular dễ mặc"]', 459000, 540000, 60, 210, 'S,M,L,XL', 'Xanh dương / Trắng', 'Cotton poplin', 'nam', 5, 3, 1, 0, '/images/products/so-mi-caro-gingham-xanh-duong-1.webp', '["/images/products/so-mi-caro-gingham-xanh-duong-1.webp","/images/products/so-mi-caro-gingham-xanh-duong-2.webp","/images/products/so-mi-caro-gingham-xanh-duong-3.webp","/images/products/so-mi-caro-gingham-xanh-duong-4.webp"]'),
  (12, 2, 'Sơ mi flannel caro đỏ đen', 'so-mi-flannel-caro-do-den', 'LUXE', 'Sơ mi flannel kẻ caro buffalo đỏ – đen to bản đặc trưng phong cách lumberjack. Vải cotton chải dày ấm, cổ bẻ với hàng nút trắng tương phản, có thể mặc như áo khoác nhẹ.', '["Caro buffalo đỏ đen","Vải flannel dày, mềm ấm","Nút trắng tương phản","Mặc riêng hoặc khoác ngoài"]', 529000, NULL, 45, 165, 'S,M,L,XL', 'Đỏ / Đen', 'Flannel cotton chải', 'nam', 4.6, 5, 0, 0, '/images/products/so-mi-flannel-caro-do-den-1.webp', '["/images/products/so-mi-flannel-caro-do-den-1.webp","/images/products/so-mi-flannel-caro-do-den-2.webp","/images/products/so-mi-flannel-caro-do-den-3.webp","/images/products/so-mi-flannel-caro-do-den-4.webp"]'),
  (13, 2, 'Sơ mi Hawaii hoạ tiết hoa dâm bụt', 'so-mi-hawaii-hoa-dam-but', 'LUXE', 'Sơ mi tay ngắn nền xanh cobalt in hoa dâm bụt trắng xen lá nhiệt đới xanh nhạt. Cổ bẻ thoáng, chất rayon rủ mát – chiếc áo không thể thiếu cho những chuyến đi biển.', '["Hoạ tiết hoa dâm bụt nhiệt đới","Tay ngắn, cổ bẻ","Rayon mềm, thoáng mát","Phong cách resort"]', 399000, NULL, 50, 98, 'S,M,L,XL', 'Xanh cobalt', 'Rayon mát', 'nam', 5, 4, 0, 1, '/images/products/so-mi-hawaii-hoa-dam-but-1.webp', '["/images/products/so-mi-hawaii-hoa-dam-but-1.webp","/images/products/so-mi-hawaii-hoa-dam-but-2.webp","/images/products/so-mi-hawaii-hoa-dam-but-3.webp","/images/products/so-mi-hawaii-hoa-dam-but-4.webp"]'),
  (14, 2, 'Sơ mi caro tartan xanh rêu', 'so-mi-caro-tartan-xanh-reu', 'LUXE', 'Sơ mi tay dài kẻ caro tartan phối xanh rêu, xám và xanh ngọc nhạt trên nền trắng. Cổ button-down đính nút, măng-sét bo gọn – dễ phối cùng quần chino hoặc jeans.', '["Caro tartan tông xanh lạnh","Cổ button-down","Cotton oxford bền màu","Tay dài, măng-sét cài nút"]', 489000, NULL, 40, 76, 'S,M,L,XL', 'Xanh rêu / Xanh ngọc', 'Cotton oxford', 'nam', 4.5, 4, 0, 0, '/images/products/so-mi-caro-tartan-xanh-reu-1.webp', '["/images/products/so-mi-caro-tartan-xanh-reu-1.webp","/images/products/so-mi-caro-tartan-xanh-reu-2.webp","/images/products/so-mi-caro-tartan-xanh-reu-3.webp","/images/products/so-mi-caro-tartan-xanh-reu-4.webp"]'),
  (15, 3, 'Túi xách tay da saffiano xanh ngọc', 'tui-xach-saffiano-xanh-ngoc', 'LUXE', 'Túi xách tay dáng thang đứng form màu xanh ngọc pastel, bề mặt da vân saffiano chống xước. Hai quai xách tròn, thẻ tag da treo bên hông và logo tam giác kim loại phía trước.', '["Da vân saffiano chống xước","Hai quai xách và thẻ tag treo","Dáng thang đứng form","Ngăn chính rộng, khoá kéo"]', 2490000, 2890000, 10, 47, NULL, 'Xanh ngọc pastel', 'Da bò vân saffiano', 'nu', 4.3, 4, 1, 0, '/images/products/tui-xach-saffiano-xanh-ngoc-1.webp', '["/images/products/tui-xach-saffiano-xanh-ngoc-1.webp","/images/products/tui-xach-saffiano-xanh-ngoc-2.webp","/images/products/tui-xach-saffiano-xanh-ngoc-3.webp"]'),
  (16, 3, 'Túi hobo da nâu cognac', 'tui-hobo-da-nau-cognac', 'LUXE', 'Túi hobo dáng mềm màu nâu cognac ấm áp, hai quai cong ôm vai. Mặt trước có ngăn khoá kéo, hai bên hông nhấn phụ kiện kim loại vàng – sang trọng mà vẫn thoải mái hằng ngày.', '["Dáng hobo mềm mại","Ngăn khoá kéo mặt trước","Phụ kiện kim loại vàng","Da nappa mềm tay"]', 1690000, NULL, 16, 63, NULL, 'Nâu cognac', 'Da bò nappa', 'nu', 4, 4, 0, 0, '/images/products/tui-hobo-da-nau-cognac-1.webp', '["/images/products/tui-hobo-da-nau-cognac-1.webp","/images/products/tui-hobo-da-nau-cognac-2.webp","/images/products/tui-hobo-da-nau-cognac-3.webp"]'),
  (17, 3, 'Túi satchel da đen đai khoá vàng', 'tui-satchel-da-den-dai-khoa', 'LUXE', 'Túi satchel đen dáng hộp với hai quai xách, mặt trước nhấn đai da ngang cùng khoá kim loại vàng. Hai bên hông gấp xếp kiểu accordion giúp túi mở rộng, đựng vừa laptop 13 inch.', '["Đai da khoá vàng mặt trước","Hông gấp xếp mở rộng","Dáng hộp đứng form","Vừa laptop 13 inch"]', 1590000, NULL, 18, 52, NULL, 'Đen', 'Da bò trơn', 'nu', 4.7, 3, 0, 1, '/images/products/tui-satchel-da-den-dai-khoa-1.webp', '["/images/products/tui-satchel-da-den-dai-khoa-1.webp","/images/products/tui-satchel-da-den-dai-khoa-2.webp","/images/products/tui-satchel-da-den-dai-khoa-3.webp"]'),
  (18, 3, 'Túi tote da xanh navy', 'tui-tote-da-xanh-navy', 'LUXE', 'Túi tote dáng chữ nhật đứng form màu xanh navy đậm, hai quai xách tròn chắc chắn. Thân túi chia mảnh với đường chỉ nổi dọc thân, tối giản và thanh lịch cho dân công sở.', '["Dáng tote chữ nhật","Đường chỉ nổi dọc thân","Quai tròn chắc chắn","Màu navy dễ phối đồ"]', 1450000, NULL, 20, 44, NULL, 'Xanh navy', 'Da bò trơn', 'nu', 4.6, 5, 0, 0, '/images/products/tui-tote-da-xanh-navy-1.webp', '["/images/products/tui-tote-da-xanh-navy-1.webp","/images/products/tui-tote-da-xanh-navy-2.webp","/images/products/tui-tote-da-xanh-navy-3.webp"]'),
  (19, 3, 'Balo da trắng nắp gập dây rút', 'balo-da-trang-nap-gap', 'LUXE', 'Balo mini màu trắng tinh với nắp gập trang trí thanh kim loại vàng, miệng túi dây rút. Hai quai đeo vai điều chỉnh độ dài bằng khoá kim loại, quai xách nhỏ phía trên tiện lợi.', '["Nắp gập viền kim loại vàng","Miệng túi dây rút","Quai đeo điều chỉnh được","Kích thước mini gọn nhẹ"]', 890000, NULL, 25, 81, NULL, 'Trắng', 'Da PU cao cấp', 'nu', 4.8, 4, 0, 0, '/images/products/balo-da-trang-nap-gap-1.webp', '["/images/products/balo-da-trang-nap-gap-1.webp","/images/products/balo-da-trang-nap-gap-2.webp","/images/products/balo-da-trang-nap-gap-3.webp"]'),
  (20, 4, 'Giày stiletto da bóng đen đế đỏ', 'giay-stiletto-da-bong-den', 'LUXE', 'Giày stiletto mũi nhọn bằng da bóng đen, gót nhọn 12cm thanh mảnh. Lót trong màu nude, đế ngoài đỏ nổi bật – món đồ kinh điển cho những buổi tiệc tối.', '["Gót nhọn 12cm","Mũi nhọn thon dài","Đế ngoài màu đỏ","Lót da nude êm chân"]', 1390000, NULL, 22, 140, '35,36,37,38,39', 'Đen', 'Da bóng, lót da', 'nu', 4.5, 4, 1, 0, '/images/products/giay-stiletto-da-bong-den-1.webp', '["/images/products/giay-stiletto-da-bong-den-1.webp","/images/products/giay-stiletto-da-bong-den-2.webp","/images/products/giay-stiletto-da-bong-den-3.webp","/images/products/giay-stiletto-da-bong-den-4.webp"]'),
  (21, 4, 'Giày cao gót ánh kim champagne', 'giay-cao-got-anh-kim-champagne', 'LUXE', 'Giày pump mũi nhọn phủ da ánh kim vàng champagne lấp lánh, gót stiletto 10cm. Đế ngoài màu đỏ, đường cắt thân giày thấp khoe mu bàn chân thon gọn.', '["Da ánh kim vàng champagne","Gót stiletto 10cm","Đế ngoài đỏ","Cổ giày khoét thấp"]', 1150000, 1350000, 18, 56, '35,36,37,38,39', 'Vàng champagne', 'Da ánh kim', 'nu', 4.3, 4, 0, 1, '/images/products/giay-cao-got-anh-kim-champagne-1.webp', '["/images/products/giay-cao-got-anh-kim-champagne-1.webp","/images/products/giay-cao-got-anh-kim-champagne-2.webp","/images/products/giay-cao-got-anh-kim-champagne-3.webp","/images/products/giay-cao-got-anh-kim-champagne-4.webp"]'),
  (22, 4, 'Sandal cao gót quai bản to đen', 'sandal-cao-got-quai-ban-to', 'LUXE', 'Sandal cao gót mũi hở với quai ngang bản rộng phía trước và quai cổ chân dạng ống in chữ trắng. Da bóng đen, gót nhọn 10cm – hiện đại, cá tính.', '["Quai ngang bản to","Quai cổ chân dạng ống","Gót nhọn 10cm","Mũi hở thoáng"]', 1290000, NULL, 15, 37, '35,36,37,38,39', 'Đen', 'Da bóng', 'nu', 5, 5, 0, 0, '/images/products/sandal-cao-got-quai-ban-to-1.webp', '["/images/products/sandal-cao-got-quai-ban-to-1.webp","/images/products/sandal-cao-got-quai-ban-to-2.webp","/images/products/sandal-cao-got-quai-ban-to-3.webp","/images/products/sandal-cao-got-quai-ban-to-4.webp"]'),
  (23, 4, 'Giày pump mũi nhọn da đen mờ', 'giay-pump-mui-nhon-da-den', 'LUXE', 'Giày pump công sở da đen mờ mũi nhọn, gót nhọn 9cm vừa phải. Lót trong da nâu cognac êm chân, thiết kế trơn tối giản đi cùng mọi trang phục.', '["Da đen mờ sang trọng","Gót 9cm dễ đi","Lót da nâu cognac","Phù hợp công sở"]', 890000, NULL, 30, 155, '35,36,37,38,39', 'Đen', 'Da bò mờ, lót da nâu', 'nu', 4.4, 5, 0, 0, '/images/products/giay-pump-mui-nhon-da-den-1.webp', '["/images/products/giay-pump-mui-nhon-da-den-1.webp","/images/products/giay-pump-mui-nhon-da-den-2.webp","/images/products/giay-pump-mui-nhon-da-den-3.webp","/images/products/giay-pump-mui-nhon-da-den-4.webp"]'),
  (24, 4, 'Giày cao gót satin đỏ cherry', 'giay-cao-got-satin-do', 'LUXE', 'Giày cao gót bọc satin đỏ cherry bóng mượt, mũi nhọn bo nhẹ và gót nhọn 8cm. Gam đỏ rực điểm nhấn cho trang phục đen hoặc trắng.', '["Satin đỏ cherry bóng","Gót 8cm vừa phải","Mũi nhọn bo nhẹ","Lót đệm êm"]', 950000, NULL, 20, 67, '35,36,37,38,39', 'Đỏ cherry', 'Satin bóng', 'nu', 4.5, 6, 0, 0, '/images/products/giay-cao-got-satin-do-1.webp', '["/images/products/giay-cao-got-satin-do-1.webp","/images/products/giay-cao-got-satin-do-2.webp","/images/products/giay-cao-got-satin-do-3.webp","/images/products/giay-cao-got-satin-do-4.webp"]'),
  (25, 5, 'Sneaker cổ cao đỏ – trắng – đen', 'sneaker-co-cao-do-trang-den', 'LUXE', 'Sneaker cổ cao phong cách bóng rổ cổ điển: mũi và gót da đỏ, thân trắng, logo đen bên hông, cổ giày và dây đen. Mảng da đỏ phía sau chần trám tạo điểm nhấn.', '["Cổ cao ôm mắt cá","Phối màu đỏ – trắng – đen","Da chần trám ở gót","Đế cao su bám tốt"]', 2890000, NULL, 25, 230, '39,40,41,42,43,44', 'Đỏ / Trắng / Đen', 'Da bò, đế cao su', 'unisex', 5, 3, 1, 0, '/images/products/sneaker-co-cao-do-trang-den-1.webp', '["/images/products/sneaker-co-cao-do-trang-den-1.webp","/images/products/sneaker-co-cao-do-trang-den-2.webp","/images/products/sneaker-co-cao-do-trang-den-3.webp","/images/products/sneaker-co-cao-do-trang-den-4.webp"]'),
  (26, 5, 'Sneaker cổ thấp hoạ tiết mũi tên đỏ', 'sneaker-co-thap-mui-ten-do', 'LUXE', 'Sneaker cổ thấp da trắng kem, nổi bật hoạ tiết mũi tên đỏ bên hông. Gót và lót cổ giày màu đỏ, viền đế đỏ – phong cách streetwear dễ phối.', '["Mũi tên đỏ bên hông","Gót và lót cổ màu đỏ","Da trắng kem dễ vệ sinh","Đế cao su viền đỏ"]', 2390000, 2690000, 20, 112, '39,40,41,42,43,44', 'Trắng kem / Đỏ', 'Da bò, đế cao su', 'unisex', 4.5, 6, 0, 1, '/images/products/sneaker-co-thap-mui-ten-do-1.webp', '["/images/products/sneaker-co-thap-mui-ten-do-1.webp","/images/products/sneaker-co-thap-mui-ten-do-2.webp","/images/products/sneaker-co-thap-mui-ten-do-3.webp","/images/products/sneaker-co-thap-mui-ten-do-4.webp"]'),
  (27, 5, 'Sneaker retro runner phối màu', 'sneaker-retro-runner-phoi-mau', 'LUXE', 'Sneaker chạy bộ phong cách retro thập niên 80 với các mảng xanh dương, đỏ, vàng chanh và kem. Đế bánh mì trắng có rãnh, dây trắng, lớp lưới thoáng khí.', '["Phối màu retro rực rỡ","Đế EVA nhẹ, êm","Mũ giày lưới thoáng khí","Phong cách chạy bộ cổ điển"]', 1790000, NULL, 30, 97, '39,40,41,42,43,44', 'Xanh / Đỏ / Vàng', 'Lưới, da lộn, đế EVA', 'unisex', 4.7, 3, 0, 0, '/images/products/sneaker-retro-runner-phoi-mau-1.webp', '["/images/products/sneaker-retro-runner-phoi-mau-1.webp","/images/products/sneaker-retro-runner-phoi-mau-2.webp","/images/products/sneaker-retro-runner-phoi-mau-3.webp","/images/products/sneaker-retro-runner-phoi-mau-4.webp"]'),
  (28, 5, 'Giày đinh bóng chày trắng – xanh rêu', 'giay-dinh-bong-chay-trang-xanh', 'LUXE', 'Giày thể thao cổ lửng thân trắng phối da xanh lục đậm, logo bên hông. Đế đinh kim loại bám sân cỏ, lưỡi gà đệm dày – dành cho bóng chày và các môn sân cỏ.', '["Đế đinh kim loại bám sân","Cổ lửng ổn định mắt cá","Phối trắng – xanh rêu","Lưỡi gà đệm dày"]', 1990000, NULL, 14, 28, '39,40,41,42,43,44', 'Trắng / Xanh rêu', 'Da tổng hợp, đế đinh kim loại', 'nam', 4.5, 6, 0, 0, '/images/products/giay-dinh-bong-chay-trang-xanh-1.webp', '["/images/products/giay-dinh-bong-chay-trang-xanh-1.webp","/images/products/giay-dinh-bong-chay-trang-xanh-2.webp","/images/products/giay-dinh-bong-chay-trang-xanh-3.webp","/images/products/giay-dinh-bong-chay-trang-xanh-4.webp"]'),
  (29, 6, 'Đồng hồ lặn mặt đen vành xoay', 'dong-ho-lan-mat-den-vanh-xoay', 'LUXE', 'Đồng hồ lặn mặt đen với vành xoay một chiều chia phút, cọc số dạ quang và lịch ngày có mắt lens phóng to ở vị trí 3 giờ. Dây kim loại phối demi vàng – thép, chống nước 200m.', '["Vành xoay chia phút","Cọc số dạ quang","Lịch ngày có lens phóng đại","Chống nước 200m"]', 11900000, 13500000, 8, 23, NULL, 'Đen / Demi vàng', 'Thép 316L, kính sapphire', 'nam', 4.7, 3, 1, 0, '/images/products/dong-ho-lan-mat-den-vanh-xoay-1.webp', '["/images/products/dong-ho-lan-mat-den-vanh-xoay-1.webp","/images/products/dong-ho-lan-mat-den-vanh-xoay-2.webp","/images/products/dong-ho-lan-mat-den-vanh-xoay-3.webp"]'),
  (30, 6, 'Đồng hồ moonphase mặt trắng vỏ vàng hồng', 'dong-ho-moonphase-mat-trang-vang-hong', 'LUXE', 'Mặt số trắng ngà tinh tế với đĩa lịch tuần trăng xanh lapis ở vị trí 6 giờ, kim và cọc vàng hồng. Vỏ vàng hồng bóng, dây da nâu sẫm chỉ khâu trắng.', '["Lịch tuần trăng (moonphase)","Vỏ vàng hồng bóng","Dây da nâu chỉ trắng","Máy cơ automatic"]', 9500000, NULL, 9, 19, NULL, 'Vàng hồng / Nâu', 'Thép mạ vàng hồng, dây da bê', 'nam', 5, 3, 0, 1, '/images/products/dong-ho-moonphase-mat-trang-vang-hong-1.webp', '["/images/products/dong-ho-moonphase-mat-trang-vang-hong-1.webp","/images/products/dong-ho-moonphase-mat-trang-vang-hong-2.webp","/images/products/dong-ho-moonphase-mat-trang-vang-hong-3.webp"]'),
  (31, 6, 'Đồng hồ chronograph vỏ vàng dây da nâu', 'dong-ho-chronograph-vo-vang-day-da', 'LUXE', 'Chronograph mặt trắng với số Ả Rập, kim xanh blued cổ điển, ba mặt phụ và lịch tuần trăng. Vỏ vàng, dây da nâu vân cá sấu với khoá gập triển khai.', '["Ba mặt phụ chronograph","Kim xanh blued","Dây da vân cá sấu","Khoá gập triển khai"]', 8900000, NULL, 11, 34, NULL, 'Vàng / Nâu', 'Thép mạ vàng, dây da vân cá sấu', 'nam', 4.8, 6, 0, 0, '/images/products/dong-ho-chronograph-vo-vang-day-da-1.webp', '["/images/products/dong-ho-chronograph-vo-vang-day-da-1.webp","/images/products/dong-ho-chronograph-vo-vang-day-da-2.webp","/images/products/dong-ho-chronograph-vo-vang-day-da-3.webp"]'),
  (32, 6, 'Đồng hồ chronograph mặt đen dây thép', 'dong-ho-chronograph-mat-den-day-thep', 'LUXE', 'Mặt số đen số La Mã kèm cửa sổ thứ – tháng và lịch tuần trăng, ba mặt phụ chronograph. Vỏ và dây thép không gỉ mắt xích, khoá bướm chắc chắn.', '["Cửa sổ thứ và tháng","Số La Mã cổ điển","Dây thép mắt xích","Khoá bướm an toàn"]', 8500000, NULL, 12, 29, NULL, 'Bạc / Đen', 'Thép không gỉ 316L', 'nam', 4.7, 6, 0, 0, '/images/products/dong-ho-chronograph-mat-den-day-thep-1.webp', '["/images/products/dong-ho-chronograph-mat-den-day-thep-1.webp","/images/products/dong-ho-chronograph-mat-den-day-thep-2.webp","/images/products/dong-ho-chronograph-mat-den-day-thep-3.webp"]'),
  (33, 6, 'Đồng hồ demi vành khía mặt xám', 'dong-ho-demi-vanh-khia-mat-xam', 'LUXE', 'Vành khía (fluted) vàng ôm mặt số xám than với cọc số La Mã và lịch ngày ở vị trí 3 giờ. Dây jubilee 5 hàng mắt phối vàng và thép – biểu tượng thanh lịch vượt thời gian.', '["Vành khía fluted mạ vàng","Dây jubilee demi","Lịch ngày vị trí 3 giờ","Hợp cả nam và nữ"]', 10500000, NULL, 10, 41, NULL, 'Demi vàng – thép / Xám', 'Thép 316L mạ vàng', 'unisex', 5, 3, 1, 0, '/images/products/dong-ho-demi-vanh-khia-mat-xam-1.webp', '["/images/products/dong-ho-demi-vanh-khia-mat-xam-1.webp","/images/products/dong-ho-demi-vanh-khia-mat-xam-2.webp","/images/products/dong-ho-demi-vanh-khia-mat-xam-3.webp"]'),
  (34, 6, 'Đồng hồ vỏ vàng hồng mặt đen dây da', 'dong-ho-vo-vang-hong-mat-den', 'LUXE', 'Mặt số đen sâu với kim và cọc vàng hồng, mặt phụ hiển thị ngày bên phải. Vỏ vàng hồng dáng tròn cổ điển, dây da đen lót da sáng màu.', '["Mặt đen kim vàng hồng","Mặt phụ hiển thị ngày","Dây da đen lót sáng","Vỏ tròn cổ điển"]', 7900000, NULL, 13, 22, NULL, 'Vàng hồng / Đen', 'Thép mạ vàng hồng, dây da bê', 'nam', 4.8, 6, 0, 0, '/images/products/dong-ho-vo-vang-hong-mat-den-1.webp', '["/images/products/dong-ho-vo-vang-hong-mat-den-1.webp","/images/products/dong-ho-vo-vang-hong-mat-den-2.webp","/images/products/dong-ho-vo-vang-hong-mat-den-3.webp"]'),
  (35, 6, 'Đồng hồ automatic thép mặt đen', 'dong-ho-automatic-thep-mat-den', 'LUXE', 'Đồng hồ automatic vỏ và dây thép bạc chải xước, mặt đen với cọc vạch dạ quang và kim lá thanh mảnh. Thiết kế thể thao – thanh lịch, đeo được mọi hoàn cảnh.', '["Máy automatic","Cọc vạch dạ quang","Thép chải xước","Dây mắt xích 3 hàng"]', 6900000, NULL, 15, 38, NULL, 'Bạc / Đen', 'Thép không gỉ chải xước', 'unisex', 4.3, 3, 0, 0, '/images/products/dong-ho-automatic-thep-mat-den-1.webp', '["/images/products/dong-ho-automatic-thep-mat-den-1.webp","/images/products/dong-ho-automatic-thep-mat-den-2.webp","/images/products/dong-ho-automatic-thep-mat-den-3.webp"]'),
  (36, 6, 'Đồng hồ nữ mặt xanh dây kim loại vàng', 'dong-ho-nu-mat-xanh-day-vang', 'LUXE', 'Mặt số xanh navy với cọc số La Mã và kim giây đỏ nổi bật. Vỏ và dây mắt xích mạ vàng PVD bền màu – món phụ kiện nữ tính và sang trọng.', '["Mặt xanh navy số La Mã","Kim giây màu đỏ","Mạ vàng PVD bền màu","Máy quartz chính xác"]', 3900000, 4500000, 20, 46, NULL, 'Vàng / Xanh navy', 'Thép mạ vàng PVD', 'nu', 4.3, 6, 0, 1, '/images/products/dong-ho-nu-mat-xanh-day-vang-1.webp', '["/images/products/dong-ho-nu-mat-xanh-day-vang-1.webp","/images/products/dong-ho-nu-mat-xanh-day-vang-2.webp","/images/products/dong-ho-nu-mat-xanh-day-vang-3.webp"]'),
  (37, 6, 'Đồng hồ tối giản mặt đen dây thép', 'dong-ho-toi-gian-mat-den', 'LUXE', 'Mặt số đen trơn tối giản với cọc vạch mảnh và lịch ngày ở vị trí 6 giờ. Vỏ và dây thép mắt xích 5 hàng sáng bóng, mỏng nhẹ khi đeo.', '["Thiết kế tối giản","Lịch ngày vị trí 6 giờ","Dây thép 5 hàng mắt","Vỏ mỏng nhẹ"]', 2900000, NULL, 25, 64, NULL, 'Bạc / Đen', 'Thép không gỉ', 'unisex', 5, 5, 0, 0, '/images/products/dong-ho-toi-gian-mat-den-1.webp', '["/images/products/dong-ho-toi-gian-mat-den-1.webp","/images/products/dong-ho-toi-gian-mat-den-2.webp"]'),
  (38, 7, 'Kính râm clubmaster đồi mồi', 'kinh-clubmaster-doi-moi', 'LUXE', 'Kính clubmaster với viền trên nhựa vân đồi mồi nâu, nửa dưới gọng kim loại vàng mảnh. Tròng xanh rêu G-15 chống tia UV400, giữ màu sắc tự nhiên.', '["Viền trên vân đồi mồi","Gọng dưới kim loại vàng","Tròng xanh rêu G-15","Chống UV400"]', 590000, NULL, 40, 175, NULL, 'Đồi mồi / Vàng', 'Acetate, kim loại', 'unisex', 4.3, 4, 1, 0, '/images/products/kinh-clubmaster-doi-moi-1.webp', '["/images/products/kinh-clubmaster-doi-moi-1.webp","/images/products/kinh-clubmaster-doi-moi-2.webp","/images/products/kinh-clubmaster-doi-moi-3.webp"]'),
  (39, 7, 'Kính phi công tròng gradient xanh', 'kinh-phi-cong-trong-gradient-xanh', 'LUXE', 'Kính aviator gọng kim loại vàng mảnh với cầu đôi kinh điển. Tròng giọt nước gradient xanh khói nhạt dần từ trên xuống, chống UV400.', '["Dáng aviator giọt nước","Cầu đôi kim loại","Tròng gradient xanh khói","Chống UV400"]', 650000, NULL, 35, 132, NULL, 'Vàng / Xanh khói', 'Kim loại, tròng polycarbonate', 'unisex', 4.6, 5, 0, 0, '/images/products/kinh-phi-cong-trong-gradient-xanh-1.webp', '["/images/products/kinh-phi-cong-trong-gradient-xanh-1.webp","/images/products/kinh-phi-cong-trong-gradient-xanh-2.webp","/images/products/kinh-phi-cong-trong-gradient-xanh-3.webp"]'),
  (40, 7, 'Kính phi công tròng xanh lá', 'kinh-phi-cong-trong-xanh-la', 'LUXE', 'Kính gọng kim loại đen cầu đôi, tròng lục giác bo góc màu xanh ngọc lá trong trẻo. Biến thể hiện đại của dáng phi công, nhẹ và thời thượng.', '["Tròng xanh lá trong","Gọng kim loại đen","Dáng lục giác bo góc","Siêu nhẹ"]', 620000, NULL, 30, 54, NULL, 'Đen / Xanh lá', 'Kim loại, tròng polycarbonate', 'unisex', 4.7, 6, 0, 1, '/images/products/kinh-phi-cong-trong-xanh-la-1.webp', '["/images/products/kinh-phi-cong-trong-xanh-la-1.webp","/images/products/kinh-phi-cong-trong-xanh-la-2.webp","/images/products/kinh-phi-cong-trong-xanh-la-3.webp"]'),
  (41, 7, 'Kính gọng trong suốt oversize', 'kinh-gong-trong-suot-oversize', 'LUXE', 'Kính gọng acetate trong suốt to bản, dáng vuông với cạnh vát góc cá tính. Đinh tán vàng ở bản lề, tròng trong suốt – có thể thay tròng cận.', '["Gọng acetate trong suốt","Dáng oversize cạnh vát","Đinh tán vàng bản lề","Lắp được tròng cận"]', 520000, NULL, 28, 61, NULL, 'Trong suốt', 'Acetate trong', 'unisex', 4.3, 4, 0, 0, '/images/products/kinh-gong-trong-suot-oversize-1.webp', '["/images/products/kinh-gong-trong-suot-oversize-1.webp","/images/products/kinh-gong-trong-suot-oversize-2.webp","/images/products/kinh-gong-trong-suot-oversize-3.webp"]'),
  (42, 7, 'Kính pixel 8-bit tròng hồng', 'kinh-pixel-8-bit', 'LUXE', 'Kính party gọng nhựa đen tạo hình pixel 8-bit, tròng hồng điểm ô pixel trắng. Món phụ kiện vui nhộn cho tiệc tùng, chụp ảnh và lễ hội.', '["Hình pixel 8-bit vui nhộn","Tròng hồng có ô pixel","Nhựa ABS siêu nhẹ","Phụ kiện tiệc & chụp ảnh"]', 190000, NULL, 60, 210, NULL, 'Đen / Hồng', 'Nhựa ABS', 'unisex', 4.5, 4, 0, 0, '/images/products/kinh-pixel-8-bit-1.webp', '["/images/products/kinh-pixel-8-bit-1.webp","/images/products/kinh-pixel-8-bit-2.webp","/images/products/kinh-pixel-8-bit-3.webp"]'),
  (43, 8, 'Bông tai giọt pha lê xanh lục bảo', 'bong-tai-giot-pha-le-xanh-luc', 'LUXE', 'Bông tai móc khoá chữ U mạ vàng, đính đá tròn xanh lục nhỏ, nối chụp vàng với mặt pha lê giọt nước giác cắt xanh lục bảo lấp lánh.', '["Pha lê giọt nước giác cắt","Móc khoá chữ U an toàn","Mạ vàng 18K","Hợp dự tiệc"]', 690000, NULL, 30, 88, NULL, 'Xanh lục / Vàng', 'Đồng mạ vàng 18K, pha lê', 'nu', 5, 3, 1, 0, '/images/products/bong-tai-giot-pha-le-xanh-luc-1.webp', '["/images/products/bong-tai-giot-pha-le-xanh-luc-1.webp","/images/products/bong-tai-giot-pha-le-xanh-luc-2.webp","/images/products/bong-tai-giot-pha-le-xanh-luc-3.webp"]'),
  (44, 8, 'Bông tai vòng tròn caro xanh – kem', 'bong-tai-vong-tron-caro-xanh', 'LUXE', 'Khuyên nụ tròn màu xanh ngọc treo mặt vòng tròn rỗng hoạ tiết caro gợn sóng xanh ngọc – kem. Chất liệu acrylic siêu nhẹ, chốt bạc 925 không gây kích ứng.', '["Hoạ tiết caro gợn sóng","Acrylic siêu nhẹ","Chốt bạc 925","Phong cách retro"]', 290000, NULL, 45, 70, NULL, 'Xanh ngọc / Kem', 'Acrylic, chốt bạc 925', 'nu', 4.6, 5, 0, 1, '/images/products/bong-tai-vong-tron-caro-xanh-1.webp', '["/images/products/bong-tai-vong-tron-caro-xanh-1.webp","/images/products/bong-tai-vong-tron-caro-xanh-2.webp","/images/products/bong-tai-vong-tron-caro-xanh-3.webp"]'),
  (45, 8, 'Bông tai lá monstera vàng nghệ', 'bong-tai-la-monstera-vang', 'LUXE', 'Khuyên nụ tròn kim loại vàng treo mặt lá monstera tạo hình bằng acrylic vàng nghệ. Thiết kế nhiệt đới nổi bật, nhẹ tai khi đeo cả ngày.', '["Tạo hình lá monstera","Màu vàng nghệ ấm","Khuyên nụ mạ vàng","Nhẹ, đeo cả ngày"]', 320000, NULL, 40, 58, NULL, 'Vàng nghệ', 'Acrylic, khuyên kim loại mạ vàng', 'nu', 5, 5, 0, 0, '/images/products/bong-tai-la-monstera-vang-1.webp', '["/images/products/bong-tai-la-monstera-vang-1.webp","/images/products/bong-tai-la-monstera-vang-2.webp","/images/products/bong-tai-la-monstera-vang-3.webp"]')
ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), name = VALUES(name), slug = VALUES(slug),
  description = VALUES(description), highlights = VALUES(highlights), price = VALUES(price),
  original_price = VALUES(original_price), sizes = VALUES(sizes), color = VALUES(color),
  material = VALUES(material), gender = VALUES(gender), rating = VALUES(rating), review_count = VALUES(review_count),
  is_featured = VALUES(is_featured), is_new = VALUES(is_new), image_url = VALUES(image_url), images = VALUES(images);

-- Xoá sản phẩm cũ không còn trong catalog (chưa có trong đơn hàng nào)
DELETE FROM products WHERE id > 45 AND id NOT IN (SELECT product_id FROM (SELECT DISTINCT product_id FROM order_items) t);

ON DUPLICATE KEY UPDATE product_id = VALUES(product_id), author_name = VALUES(author_name),
  rating = VALUES(rating), comment = VALUES(comment);
